'use strict';
const isSupplier=document.body?.dataset?.accountKind==='supplier',paymentKind=isSupplier?'payment':'repayment';
const $=selector=>document.querySelector(selector),customerId=new URLSearchParams(location.search).get('id');
const uuid=value=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value||'');
const format=value=>new Intl.NumberFormat('en-US').format(BigInt(value));
const date=value=>new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'short'}).format(new Date(value));
const statementOwner=KashierData.userId(),active=()=>KashierData.loggedIn()&&KashierData.userId()===statementOwner;
let statement=null,requestNumber=0;
function node(tag,text,className){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;if(className)element.className=className;return element;}
function invalidate(){requestNumber++;statement=null;$('#statement-paper').hidden=true;$('#statement-paper').replaceChildren();$('#statement-print').disabled=$('#statement-csv').disabled=true;$('#statement-load').disabled=false;$('#statement-status').textContent='بۆ پیشاندانی کشفی ئەم ماوەیە دوگمەی پیشاندان دابگرە.';}
function validDate(value){if(!value)return true;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||value<'0001-01-01')return false;try{return new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;}catch{return false;}}
function validate(data,from,to){if(!data||(isSupplier?data.supplier:data.customer)?.id!==customerId||data.from!==from||data.to!==to||data.currency!=='IQD'||data.timezone!=='Asia/Baghdad'||!Array.isArray(data.rows)||data.count!==data.rows.length||data.rows.length>5000)throw Error('کشفەکە تەواو نییە یان وەڵامەکە پشتڕاست نەکرایەوە.');const profile=isSupplier?data.supplier:data.customer;if(typeof profile.name!=='string'||!profile.name.trim()||!(profile.phone==null||typeof profile.phone==='string'))throw Error('زانیاریی حساب نادروستە.');const integer=value=>{if(typeof value!=='string'||! /^-?\d+$/.test(value))throw Error('بڕی حساب نادروستە.');return BigInt(value);};let balance=integer(data.opening),charges=0n,repayments=0n,reversals=0n,returnsTotal=0n,last=0n;for(const row of data.rows){if(!row||!uuid(row.id)||typeof row.note!=='string'||!Number.isFinite(Date.parse(row.created_at))||!(row.reference_no==null||typeof row.reference_no==='string'))throw Error('زانیاریی تۆمار نادروستە.');for(const key of ['sale_id','purchase_id','cash_movement_id'])if(row[key]!=null&&!uuid(row[key]))throw Error('سەرچاوەی تۆمار نادروستە.');const amount=integer(row.amount),delta=integer(row.delta),order=integer(row.movement_no),allowed=isSupplier?['charge','payment','return']:['charge','repayment','reversal'];let expected;if(row.kind==='charge')expected=amount;else if(row.kind===paymentKind)expected=-amount;else if(isSupplier&&row.kind==='return'){const cash=integer(row.cash_refund),debt=integer(row.debt_reversed);if(cash<0n||debt<0n||cash+debt!==amount)throw Error('دابەشکردنی گەڕاندنەوەی کڕین نادروستە.');expected=-debt;returnsTotal+=amount;reversals+=debt;}else{expected=-amount;reversals+=amount;}if(amount<=0n||order<=last||!allowed.includes(row.kind)||delta!==expected)throw Error('ڕیزبەندی یان بڕی مامەڵە نادروستە.');last=order;balance+=delta;if(balance!==integer(row.balance))throw Error('باڵانسی مامەڵەکان یەک ناگرێتەوە.');if(row.kind==='charge')charges+=amount;else if(row.kind===paymentKind)repayments+=amount;}
 if(balance!==integer(data.closing)||charges!==integer(data.charges)||repayments!==integer(isSupplier?data.payments:data.repayments)||reversals!==integer(data.reversals)||(isSupplier&&returnsTotal!==integer(data.returns_total)))throw Error('کۆی حساب یەک ناگرێتەوە.');date(data.generated_at);}
function render(data){const profile=isSupplier?data.supplier:data.customer;const paper=$('#statement-paper');paper.replaceChildren(node('h2','کاشێر'),node('h3',isSupplier?'کشفی حسابی دابینکەر':'کشفی حسابی کڕیار'));const meta=node('div',undefined,'statement-meta');meta.append(node('div',(isSupplier?'دابینکەر: ':'کڕیار: ')+profile.name));if(profile.phone)meta.append(node('div','مۆبایل: '+profile.phone));meta.append(node('div','ماوە: '+(data.from||'لە سەرەتاوە')+' — '+(data.to||'تا کاتی خوێندنەوە')),node('div','کاتی خوێندنەوە: '+date(data.generated_at)+' · بەغدا'),node('div','دراو: دیناری عێراقی / دیناری عێراقی · ژمارەی مامەڵە: '+data.count));paper.append(meta);const totals=node('div',undefined,'statement-totals');const totalRows=isSupplier?[['باڵانسی سەرەتا',data.opening],['کۆی قەرزی زیادکراو',data.charges],['پارەی دراو بە دابینکەر',data.payments],['کۆی کڕینی گەڕێندراوە',data.returns_total],['قەرزی دابینکەر هەڵوەشاوە',data.reversals],['باڵانسی کۆتایی',data.closing]]:[['باڵانسی سەرەتا',data.opening],['کۆی قەرزی زیادکراو',data.charges],['کۆی پارەی وەرگیراو',data.repayments],['قەرزی هەڵوەشاوە بە گەڕاندنەوە',data.reversals],['باڵانسی کۆتایی',data.closing]];for(const [label,value] of totalRows){const cell=node('div');cell.append(node('span',label),node('strong',format(value),'numeric'));totals.append(cell);}paper.append(totals);
 if(!data.rows.length)paper.append(node('p','لەو ماوەیەدا هیچ مامەڵەیەک تۆمار نەکراوە.','statement-empty'));else{const wrap=node('div',undefined,'statement-table-wrap'),table=node('table'),head=node('thead'),header=node('tr');table.append(node('caption','قەرز، پارەدان و گەڕاندنەوەکان بە ڕیزبەندی تۆمارکردن','sr-only'));for(const title of ['تۆمار','بەروار / بەغدا','جۆر','قەرز زیادکراو',isSupplier?'پارەی دراو':'پارەی وەرگیراو',isSupplier?'گەڕاندنەوەی کڕین':'قەرزی هەڵوەشاوە','باڵانس','تێبینی']){const th=node('th',title);th.scope='col';header.append(th);}head.append(header);table.append(head);const body=node('tbody');for(const entry of data.rows){const row=node('tr'),source=node('td',StatementExport.reference(entry));if(isSupplier&&uuid(entry.purchase_id)){const link=node('a','پسوولەی کڕین');link.href='purchase-receipt.html?id='+entry.purchase_id;source.append(node('br'),link);}if(uuid(entry.sale_id)){const link=node('a','پسوولە');link.href='receipt.html?id='+entry.sale_id;source.append(node('br'),link);}const kind=StatementExport.kindLabel(entry,isSupplier);let note=entry.note;if(isSupplier&&entry.kind==='return')note+=' · قەرزی هەڵوەشاوە: '+format(entry.debt_reversed)+' · پارەی گەڕاوە: '+format(entry.cash_refund)+' دینار';row.append(source,node('td',date(entry.created_at)),node('td',kind),node('td',entry.kind==='charge'?format(entry.amount):'—','numeric'),node('td',entry.kind===paymentKind?format(entry.amount):'—','numeric'),node('td',isSupplier&&entry.kind==='return'||!isSupplier&&entry.kind==='reversal'?format(entry.amount):'—','numeric'),node('td',format(entry.balance),'numeric'),node('td',note));body.append(row);}table.append(body);wrap.append(table);paper.append(wrap);}paper.append(node('p',isSupplier?'لە کڕینی تۆمارکراو لە حساب، گەڕاندنەوە سەرەتا قەرزی ماوەی هەمان پسوولە هەڵدەوەشێنێتەوە؛ زیادەکە پارەی گەڕاوە بۆ قاسە دەبێت. بۆ کڕینی بەبێ حسابی قەرز، گۆڕانی بڕ ـی قەرز سفرە. تۆماری کڕینی سەرەکی ناسڕێتەوە.':'باڵانسەکان تایبەتن بە ماوەی دیاریکراو. پارەدان لە حسابی گشتی کڕیار کەم دەبێتەوە؛ گەڕاندنەوەی فرۆشتنی قەرزیش وەک تۆمارێکی پێچەوانە قەرز کەم دەکات و تۆماری سەرەکی ناسڕێتەوە.','statement-footnote'));paper.hidden=false;}
async function load(){invalidate();const request=++requestNumber;$('#statement-status').textContent='';if(!uuid(customerId)){$('#statement-status').textContent=(isSupplier?'ناسنامەی دابینکەر':'ناسنامەی کڕیار')+' نادروستە؛ لە لیستەکەوە هەڵیبژێرە.';return;}if(!active()){location.replace('auth.html?next='+encodeURIComponent((isSupplier?'supplier-statement.html?id=':'statement.html?id=')+customerId));return;}const from=$('#statement-from').value||null,to=$('#statement-to').value||null;if(!$('#statement-form').reportValidity()||!validDate(from)||!validDate(to)||(from&&to&&from>to)){$('#statement-status').textContent='بەروارەکان بپشکنە؛ سەرەتا نابێت دوای کۆتایی بێت.';return;}$('#statement-load').disabled=true;$('#statement-status').textContent='خوێندنەوەی کشفی حساب…';try{const data=await (isSupplier?KashierData.getSupplierStatement(customerId,from,to):KashierData.getCustomerStatement(customerId,from,to));if(request!==requestNumber)return;if(!active())throw Error('هەژمارەکە گۆڕاوە؛ دووبارە بچۆ ژوورەوە.');validate(data,from,to);render(data);statement=data;$('#statement-status').textContent='کشفەکە تەواوە. بۆ زانیاری نوێ دوگمەی نوێکردنەوە دابگرە.';$('#statement-print').disabled=$('#statement-csv').disabled=false;}catch(error){if(request===requestNumber){statement=null;$('#statement-paper').hidden=true;$('#statement-print').disabled=$('#statement-csv').disabled=true;$('#statement-status').textContent=(globalThis.KashierLocale?.message(error.message)??error.message);}}finally{if(request===requestNumber)$('#statement-load').disabled=false;}}
$('#statement-form').addEventListener('submit',event=>{event.preventDefault();if(!$('#statement-load').disabled)load();});for(const selector of ['#statement-from','#statement-to'])$(selector).addEventListener('input',invalidate);$('#statement-all').addEventListener('click',()=>{$('#statement-from').value='';$('#statement-to').value='';load();});$('#statement-print').addEventListener('click',()=>{if(usable()&&!$('#statement-print').disabled)window.print();});if(uuid(customerId)){$('#back-customer').href=(isSupplier?'supplier.html?id=':'customer.html?id=')+customerId;$('#back-customer').textContent=isSupplier?'حسابی دابینکەر ←':'حسابی کڕیار ←';}load();

function usable(){if(!active()){invalidate();$('#statement-status').textContent='هەژمارەکە گۆڕاوە؛ دووبارە بچۆ ژوورەوە.';return false;}return Boolean(statement);}
$('#statement-csv').addEventListener('click',()=>{if(!usable())return;const url=URL.createObjectURL(new Blob([StatementExport.csv(statement,isSupplier)],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=url;a.download='kashier-'+(isSupplier?'supplier':'customer')+'-statement-'+customerId+'-'+(statement.from||'all')+'-'+(statement.to||'latest')+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
window.addEventListener('beforeprint',()=>{if(!active())invalidate();});window.addEventListener('pagehide',invalidate);window.addEventListener('pageshow',e=>{if(e.persisted)invalidate();});
